-- ============================================================================
-- Initial Stock + Stock Ledger for ALL 100 products
-- WH-JKT: 50 units, WH-BDG: 30 units per product
-- Regex covers all ELEC-/OFC-/RAW-/SPR- SKUs (including new ones)
-- ============================================================================
SET @rita_id = (SELECT id FROM users WHERE email = 'admin@example.com');

-- Only the opening row: re-running used to reset quantity to 50 while the
-- ledger kept every later movement, breaking stock = SUM(ledger).
INSERT INTO product_stocks (product_id, warehouse_id, quantity)
SELECT p.id, w.id, 50
FROM products p CROSS JOIN warehouses w
WHERE w.code = 'WH-JKT' AND p.sku REGEXP '^(ELEC|OFC|RAW|SPR)-'
  AND NOT EXISTS (SELECT 1 FROM product_stocks ps WHERE ps.product_id = p.id AND ps.warehouse_id = w.id);

-- Only the opening row: re-running used to reset quantity to 30 while the
-- ledger kept every later movement, breaking stock = SUM(ledger).
INSERT INTO product_stocks (product_id, warehouse_id, quantity)
SELECT p.id, w.id, 30
FROM products p CROSS JOIN warehouses w
WHERE w.code = 'WH-BDG' AND p.sku REGEXP '^(ELEC|OFC|RAW|SPR)-'
  AND NOT EXISTS (SELECT 1 FROM product_stocks ps WHERE ps.product_id = p.id AND ps.warehouse_id = w.id);

INSERT INTO stock_ledger (product_id, warehouse_id, type, qty, ref_type, ref_id, note, done_by_user_id)
SELECT p.id, w.id, 'Adjustment', 50, NULL, NULL, 'Initial seed', @rita_id
FROM products p CROSS JOIN warehouses w
WHERE w.code = 'WH-JKT' AND p.sku REGEXP '^(ELEC|OFC|RAW|SPR)-'
  AND NOT EXISTS (SELECT 1 FROM stock_ledger sl WHERE sl.product_id = p.id AND sl.warehouse_id = w.id AND sl.note = 'Initial seed');

INSERT INTO stock_ledger (product_id, warehouse_id, type, qty, ref_type, ref_id, note, done_by_user_id)
SELECT p.id, w.id, 'Adjustment', 30, NULL, NULL, 'Initial seed', @rita_id
FROM products p CROSS JOIN warehouses w
WHERE w.code = 'WH-BDG' AND p.sku REGEXP '^(ELEC|OFC|RAW|SPR)-'
  AND NOT EXISTS (SELECT 1 FROM stock_ledger sl WHERE sl.product_id = p.id AND sl.warehouse_id = w.id AND sl.note = 'Initial seed');


