-- Purchase Orders -- 50 total
-- Distribution: 10 Draft, 12 Ordered, 8 PartiallyReceived, 15 Received, 5 Cancelled
-- ============================================================================
SET @wh_jkt = (SELECT id FROM warehouses WHERE code = 'WH-JKT');
SET @wh_bdg = (SELECT id FROM warehouses WHERE code = 'WH-BDG');

SET @sup1  = (SELECT id FROM suppliers WHERE name = 'PT Sumber Elektronik Jaya' ORDER BY id ASC LIMIT 1);
SET @sup2  = (SELECT id FROM suppliers WHERE name = 'CV Mitra Kertas Abadi' ORDER BY id ASC LIMIT 1);
SET @sup3  = (SELECT id FROM suppliers WHERE name = 'PT Baja Nusantara' ORDER BY id ASC LIMIT 1);
SET @sup4  = (SELECT id FROM suppliers WHERE name = 'UD Plastik Sejahtera' ORDER BY id ASC LIMIT 1);
SET @sup5  = (SELECT id FROM suppliers WHERE name = 'PT Sparepart Prima' ORDER BY id ASC LIMIT 1);
SET @sup6  = (SELECT id FROM suppliers WHERE name = 'PT Logam Jaya' ORDER BY id ASC LIMIT 1);
SET @sup7  = (SELECT id FROM suppliers WHERE name = 'CV Chemika Solusi' ORDER BY id ASC LIMIT 1);
SET @sup8  = (SELECT id FROM suppliers WHERE name = 'PT Tekno Komponen' ORDER BY id ASC LIMIT 1);
SET @sup9  = (SELECT id FROM suppliers WHERE name = 'UD Kertas Berkualitas' ORDER BY id ASC LIMIT 1);
SET @sup10 = (SELECT id FROM suppliers WHERE name = 'PT Baja Ringan Indonesia' ORDER BY id ASC LIMIT 1);

-- PO 1-10: Draft
