-- PO 23-30: PartiallyReceived (with ledger + stock)
INSERT INTO purchase_orders (supplier_id, destination_warehouse_id, status, order_date, note, created_by) SELECT @sup1, @wh_jkt, 'PartiallyReceived', CURDATE() - INTERVAL 5 DAY, 'Seed PO 23 Partial', @rita_id WHERE NOT EXISTS (SELECT 1 FROM purchase_orders WHERE note = 'Seed PO 23 Partial'); SET @po23 = (SELECT id FROM purchase_orders WHERE note = 'Seed PO 23 Partial'); INSERT INTO purchase_order_items (purchase_order_id, product_id, qty_ordered, qty_received, purchase_price) SELECT @po23, p.id, 80, 35, p.purchase_price FROM products p WHERE p.sku = 'ELEC-012' AND NOT EXISTS (SELECT 1 FROM purchase_order_items WHERE purchase_order_id = @po23 AND product_id = p.id); INSERT INTO stock_ledger (product_id, warehouse_id, type, qty, ref_type, ref_id, note, done_by_user_id) SELECT p.id, @wh_jkt, 'Receipt', 35, 'PO', @po23, NULL, @rita_id FROM products p WHERE p.sku = 'ELEC-012' AND NOT EXISTS (SELECT 1 FROM stock_ledger WHERE ref_type='PO' AND ref_id=@po23 AND product_id=p.id); SET @po23a=ROW_COUNT(); UPDATE product_stocks ps JOIN products p ON p.sku='ELEC-012' SET ps.quantity=ps.quantity+35 WHERE ps.product_id=p.id AND ps.warehouse_id=@wh_jkt AND @po23a=1;
